// Обработка нажатия на среднюю клавишу мышки#include "stdafx.h"#include "MnemoWnd.h"#include "Queue.h"#include "QueueAPM.h"#include "QueueWnd.h"//-----------------------------------------------------------------------------bool EditSensor( CQueueWnd* wnd, char* szName, SQueue& q, DWORD dwShift, DWORD dwSizeT );//-----------------------------------------------------------------------------#define DefineMouseR LPBYTE& szQueue,SQueue& q,POINT& point,CQueueWnd* wnd//-----------------------------------------------------------------------------int MouseNullR(DefineMouseR)  {  return SkipQueue(szQueue);  }//-----------------------------------------------------------------------------#define MACROS( EMPTY, STRUCT, NAME  ) \int MouseR##EMPTY(DefineMouseR)\  {\  QueueM(STRUCT);\  if ( ::PtInRect( &p->mRect, point ) )\    if ( p->dwSizeT != 0 )\      {\      EditSensor( wnd, NAME, q, p->dwShift, p->dwSizeT );\      return 0;\      }\  return 1;\  }#include "Rect.hpp"//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int MouseQueueM(CQueueWnd* wnd,SQueue& q,POINT point)  {  if ( !::IsMnemoStyle(MNEMO_EDIT) )    return -1;  typedef int (*LPFuncMouse)(DefineMouseR);  static  LPFuncMouse gs_funcMouse[TYPE_UNKNOWN+1];  static bool bInit = true;  if ( bInit )    {    bInit=false;    for ( int n = 0; n < TYPE_UNKNOWN+1; n++ )      gs_funcMouse[n] = MouseNullR;    //    #define MACROS( EMPTY, STRUCT, NAME  ) gs_funcMouse[EMPTY] = MouseR##EMPTY;    #include "Rect.hpp"    }  //  if ( *q.szName == '\0' )    return -1;  //  LPBYTE szQueue = q.Dyna.szQueue;  if ( szQueue )    {    int n = 0;    unsigned char type;    while ( gs_funcMouse[type = *szQueue](szQueue,q,point,wnd) ) n++;    if ( type != TYPE_NULL )    return (type != TYPE_NULL)?n:-1;    }  //  if ( ::IsMnemoStyle(MNEMO_HIDE_SCN) )    {    szQueue = q.Stat.szQueue;    if ( szQueue )      {      int n = 0;      unsigned char type;      while ( gs_funcMouse[type = *szQueue](szQueue,q,point,wnd) ) n++;      return (type != TYPE_NULL)?1000000+n:-1;      }    }  //  return -1;  }//-----------------------------------------------------------------------------